        customer = self._customers.get(order.customer_id)
        customer_name = customer.name if customer is not None else ""
        lines = []
        for item in order.items:
            product = self._catalog.get(item.sku)
            product_name = product.name if product is not None else ""
            lines.append({"sku": item.sku, "name": product_name, "quantity": item.quantity})
        return Response(200, {"order_id": order.order_id, "customer_name": customer_name, "lines": lines})

    def handle_low_stock(self, threshold: Any) -> Response:
        try:
            threshold_int = require_non_negative_int(threshold, "threshold")
        except InvalidRequest as exc:
            return bad_request(exc)
        stock_levels = self._stock.all_levels()
        low_stock_products = []
        for product in self._catalog.list_all():
            if product.active and stock_levels.get(product.sku, 0) < threshold_int:
                low_stock_products.append({
                    "sku": product.sku,
                    "name": product.name,
                    "on_hand": stock_levels.get(product.sku, 0)
                })
        low_stock_products.sort(key=lambda p: (p["on_hand"], p["sku"]))
        return Response(200, {"products": low_stock_products})

    def handle_restock(self, request: dict[str, Any]) -> Response:
        try:
            sku = require_str(request, "sku")
            quantity = require_positive_int(request.get("quantity"), "quantity")
        except InvalidRequest as exc:
            return bad_request(exc)
        product = self._catalog.get(sku)
        if product is None or not product.active:
            return not_found("product")
        current_level = self._stock.get(sku)
        new_level = current_level + quantity
        self._stock.set(sku, new_level)
        return Response(200, {"sku": sku, "on_hand": new_level})

    def handle_fulfilment_summary(self) -> Response:
        open_orders = 0
        units_to_pick = 0
        for order in self._orders.list_all():
            if order.status != "cancelled":
                open_orders += 1
                for item in order.items:
                    units_to_pick += item.quantity
        stock_levels = self._stock.all_levels()
        low_stock_products = 0
        for product in self._catalog.list_all():
            if product.active and stock_levels.get(product.sku, 0) < 5:
                low_stock_products += 1
        return Response(200, {
            "open_orders": open_orders,
            "units_to_pick": units_to_pick,
            "low_stock_products": low_stock_products
        })
